"""Download Space-Track GP history for the February 2022Starlink Group 4-7 event.The script:1. Logs into Space-Track.2. Queries historical orbital elements from February 2022.3. Restricts results to the Starlink 4-7 launch group.4. Saves the raw orbital history as JSON."""from pathlib import Pathimport jsonimport osimport requests# PathsPROJECT_ROOT = Path(__file__).resolve().parent.parentRAW_DATA_DIR = (    PROJECT_ROOT    / "data"    / "raw")RAW_DATA_DIR.mkdir(    parents=True,    exist_ok=True,)OUTPUT_FILE = (    RAW_DATA_DIR    / "starlink_2022_group_4_7_gp_history.json")CATALOG_OUTPUT_FILE = (    RAW_DATA_DIR    / "starlink_2022_group_4_7_satcat.json")# Space-Track settingsLOGIN_URL = (    "https://www.space-track.org/ajaxauth/login")BASE_QUERY_URL = (    "https://www.space-track.org/basicspacedata/query")# Starlink Group 4-7 has international designatorLAUNCH_PREFIX = "2022-010"# Window around the February 3, 2022 launch and storm.START_DATE = "2022-02-03"END_DATE = "2022-02-15"# Credentialsdef get_credentials():    username = os.getenv(        "SPACETRACK_USERNAME"    )    password = os.getenv(        "SPACETRACK_PASSWORD"    )    if not username or not password:        raise ValueError(            "\nSpace-Track credentials were not found.\n\n"            "Set these environment variables first:\n"            "SPACETRACK_USERNAME\n"            "SPACETRACK_PASSWORD\n"        )    return username, passworddef save_payload_catalog(    payload_catalog,):    with open(        CATALOG_OUTPUT_FILE,        "w",        encoding="utf-8",    ) as file:        json.dump(            payload_catalog,            file,            indent=2,        )    print(        f"\nSaved Starlink payload catalog to:\n"        f"{CATALOG_OUTPUT_FILE}"    )    # Logindef login_to_spacetrack(    session,    username,    password,):    print(        "Logging into Space-Track..."    )    response = session.post(        LOGIN_URL,        data={            "identity": username,            "password": password,        },        timeout=30,    )    response.raise_for_status()    # Space-Track sometimes returns HTTP 200 even    # when authentication fails, so also check that    # the session has cookies.    if not session.cookies:        raise RuntimeError(            "Space-Track login may have failed. "            "No session cookies were returned."        )    print(        "Space-Track login successful."    )# Download GP historydef get_starlink_norad_ids(session):    """    Find cataloged objects associated with    Starlink Group 4-7.    Launch:        Year = 2022        Launch number = 10    """    print(        "\nFinding NORAD IDs for "        "Starlink Group 4-7..."    )    query_url = (        f"{BASE_QUERY_URL}"        f"/class/satcat"        f"/LAUNCH_YEAR/2022"        f"/LAUNCH_NUM/10"        f"/orderby/NORAD_CAT_ID%20asc"        f"/format/json"    )    response = session.get(        query_url,        timeout=120,    )    response.raise_for_status()    try:        records = response.json()    except requests.exceptions.JSONDecodeError:        print(            "\nSpace-Track did not return "            "valid JSON."        )        print(            response.text[:1000]        )        raise    if not records:        raise ValueError(            "Space-Track returned no catalog "            "objects for launch year 2022, "            "launch number 10."        )    print(        f"\nCataloged objects returned: "        f"{len(records)}\n"    )    norad_ids = []        payload_catalog = []    for record in records:        norad_id = record.get(            "NORAD_CAT_ID"        )        object_name = (            record.get("SATNAME")            or record.get("OBJECT_NAME")            or ""        )        international_designator = (            record.get("INTLDES")            or record.get("OBJECT_ID")            or ""        )        object_type = record.get(            "OBJECT_TYPE",            ""        )        print(            f"NORAD {norad_id}: "            f"{object_name} | "            f"{international_designator} | "            f"{object_type}"        )        if (            norad_id is not None            and object_type == "PAYLOAD"        ):            norad_ids.append(                str(norad_id)            )                        payload_catalog.append(                {                    "norad_id":                        int(norad_id),                            "satellite_name":                        object_name,                            "object_id":                        international_designator,                            "object_type":                        object_type,                            "decay_date":                        record.get(                            "DECAY"                        ),                }            )    return norad_ids, payload_catalogdef download_gp_history(    session,    norad_ids,):    """    Download historical orbital elements for the    cataloged Starlink Group 4-7 objects.    """    print(        "\nDownloading Starlink 4-7 "        "orbital history..."    )    norad_query = ",".join(        norad_ids    )    query_url = (        f"{BASE_QUERY_URL}"        f"/class/gp_history"        f"/NORAD_CAT_ID/{norad_query}"        f"/EPOCH/{START_DATE}--{END_DATE}"        f"/orderby/NORAD_CAT_ID%20asc,EPOCH%20asc"        f"/format/json"    )    response = session.get(        query_url,        timeout=120,    )    response.raise_for_status()    try:        records = response.json()    except requests.exceptions.JSONDecodeError:        print(            "\nSpace-Track did not "            "return valid JSON."        )        print(            response.text[:1000]        )        raise    if not records:        raise ValueError(            "Space-Track found the launch "            "objects, but returned no GP "            "history for the requested "            "February 2022 date range."        )    print(        f"Downloaded {len(records)} "        f"orbital records."    )    return records# Inspect downloaded objectsdef summarize_objects(    records,):    objects = {}    for record in records:        norad_id = record.get(            "NORAD_CAT_ID"        )        object_name = record.get(            "OBJECT_NAME"        )        object_id = record.get(            "OBJECT_ID"        )        if norad_id not in objects:            objects[norad_id] = {                "object_name":                    object_name,                "object_id":                    object_id,            }    print(        f"\nUnique tracked objects: "        f"{len(objects)}"    )    print(        "\nObjects returned:\n"    )    for norad_id, info in sorted(        objects.items(),        key=lambda x: int(x[0]),    ):        print(            f"NORAD {norad_id}: "            f"{info['object_name']} "            f"({info['object_id']})"        )# Save raw JSONdef save_records(    records,):    with open(        OUTPUT_FILE,        "w",        encoding="utf-8",    ) as file:        json.dump(            records,            file,            indent=2,        )    print(        f"\nSaved raw orbital history to:\n"        f"{OUTPUT_FILE}"    )# Maindef main():    username, password = (        get_credentials()    )    with requests.Session() as session:        login_to_spacetrack(            session,            username,            password,        )                       norad_ids, payload_catalog = (            get_starlink_norad_ids(                session            )        )                records = download_gp_history(            session,            norad_ids,        )    save_payload_catalog(        payload_catalog    )        summarize_objects(        records    )    save_records(        records    )if __name__ == "__main__":    main()